import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_BASE = 'http://localhost:5000';

function App() {
  const [courses, setCourses] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [assignments, setAssignments] = useState([]);
  const [newAssignment, setNewAssignment] = useState({
    name: '', description: '', due_at: '', points_possible: 10
  });
  const [announcement, setAnnouncement] = useState({ title: '', message: '' });

  useEffect(() => {
    axios.get(`${API_BASE}/courses`).then(res => setCourses(res.data));
  }, []);

  const fetchAssignments = (courseId) => {
    setSelectedCourse(courseId);
    axios.get(`${API_BASE}/courses/${courseId}/assignments`)
      .then(res => setAssignments(res.data));
  };

  const postAssignment = () => {
    let dueAtIso = newAssignment.due_at
      ? new Date(newAssignment.due_at).toISOString()
      : undefined;

    axios.post(`${API_BASE}/courses/${selectedCourse}/assignments`, {
      assignment: {
        name: newAssignment.name,
        submission_types: ['online_text_entry'],
        due_at: dueAtIso,
        points_possible: newAssignment.points_possible
      }
    })
    .then(() => alert("Assignment created!"));
  };

  const postAnnouncement = () => {
    axios.post(`${API_BASE}/courses/${selectedCourse}/announcements`, announcement)
      .then(() => alert("Announcement posted!"));
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Canvas LMS Dashboard</h1>

      <h3>All Courses</h3>
      <ul>
        {courses.map(course => (
          <li key={course.id}>
            {course.name || course.id} - 
            <button onClick={() => fetchAssignments(course.id)}>View Assignments</button>
          </li>
        ))}
      </ul>

      {selectedCourse && (
        <>
          <h3>Assignments for Course ID: {selectedCourse}</h3>
          <ul>
            {assignments.map(a => <li key={a.id}>{a.name}</li>)}
          </ul>

          {/* <h4>Create Assignment</h4>
          <input placeholder="Name" onChange={e => setNewAssignment({ ...newAssignment, name: e.target.value })} />
          <input placeholder="Description" onChange={e => setNewAssignment({ ...newAssignment, description: e.target.value })} />
          <input type="datetime-local" onChange={e => setNewAssignment({ ...newAssignment, due_at: e.target.value })} />
          <button onClick={postAssignment}>Submit Assignment</button>

          <h4>Post Announcement</h4>
          <input placeholder="Title" onChange={e => setAnnouncement({ ...announcement, title: e.target.value })} />
          <input placeholder="Message" onChange={e => setAnnouncement({ ...announcement, message: e.target.value })} />
          <button onClick={postAnnouncement}>Send Announcement</button> */}
        </>
      )}
    </div>
  );
}

export default App;
